# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps


# ---
def spans(*texts):
    return [parse_span(text) for text in texts]


class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = find_gaps(
            spans("09:00-12:00", "13:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(
            result, ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_edges(self):
        result = find_gaps(
            spans("10:00-11:00"), parse_span("09:00-12:00")
        )
        self.assertEqual(
            result,
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
            ],
        )

    def test_overlapping_spans_leave_no_gap(self):
        result = find_gaps(
            spans("09:00-13:00", "12:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(result, [])

    def test_nobody_working_is_one_gap(self):
        result = find_gaps([], parse_span("09:00-17:00"))
        self.assertEqual(
            result, ["gap 09:00-17:00 (480 min)"]
        )

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(
                spans("08:00-12:00"),
                parse_span("09:00-17:00"),
            )


if __name__ == "__main__":
    unittest.main()
